INSERT INTO `Product` VALUES ('cmpjy28az000jzh6swnhxx9yn','Fresh Pineapple Cake','pineapple-cake-500g','Refreshing pineapple-flavoured sponge with fresh cream and real pineapple pieces.','Tropical pineapple with fresh cream layers',425,NULL,'[\"https://res.cloudinary.com/dvw9o0f8z/image/upload/v1780254112/blissbakery/products/1_1freshananashcake.jpg\"]',0,0,0,1,NULL,'[\"birthday\",\"celebration\",\"retirement\"]','[\"mom\",\"dad\",\"friend\"]','Serves 4-6 people','cmpjy288c0002zh6szx1noo5o','2026-05-24 15:40:36.875','2026-05-31 19:07:57.951',NULL,NULL),('cmpjy28az000kzh6sx2w33kxg','Vanilla Cream Cake','vanilla-cream-cake-500g','Our signature eggless vanilla cake made with the finest ingredients. Light, moist sponge layered with silky vanilla cream and topped with fresh cream rosettes. Perfect for any celebration.','Light, fluffy eggless vanilla sponge with fresh cream frosting',450,NULL,'[\"https://res.cloudinary.com/dvw9o0f8z/image/upload/v1780254113/blissbakery/products/1-1mangovanilla.jpg\"]',1,0,1,1,NULL,'[\"birthday\",\"celebration\",\"retirement\"]','[\"kids\",\"friend\",\"mom\"]','Serves 4-6 people','cmpjy288c0002zh6szx1noo5o','2026-05-24 15:40:36.875','2026-05-31 19:07:57.967',NULL,NULL),('cmpjy28az000lzh6s961o8gmw','Butterscotch Cake','butterscotch-cake-500g','Soft butterscotch sponge with butterscotch cream, finished with crunchy caramel praline. A crowd favourite.','Creamy butterscotch with crunchy praline topping',475,NULL,'[\"https://res.cloudinary.com/dvw9o0f8z/image/upload/v1780254114/blissbakery/products/1779973988539-r9z34p.jpg\"]',0,0,0,1,NULL,'[]','[]','Serves 4-6 people','cmpjy288c0002zh6szx1noo5o','2026-05-24 15:40:36.875','2026-06-01 15:19:53.990','[]',NULL),('cmpjy28az000mzh6s0bioqdcb','Chocolate Truffle Cake','chocolate-truffle-cake-500g','Indulge in layers of rich chocolate sponge covered with luxurious dark chocolate ganache. A chocolate lover\'s dream — 100% eggless.','Rich dark chocolate ganache over moist chocolate sponge',550,NULL,'[\"h